// oc-sw.js: the Web Push service worker for Open WebUI (docs/install/web-push.md).
// Serve it at /oc-sw.js. With offline open on (the proxy sets OFFLINE, see
// below) it also keeps the app and the chats read last, so Open WebUI opens
// on a slow network or none; with it off it never caches or intercepts a request.
self.addEventListener("install", () => self.skipWaiting());
self.addEventListener("activate", (e) => e.waitUntil((async () => {
  if (!OFFLINE) await dropCaches(() => true);   // turned off: nothing of it stays on the device
  await self.clients.claim();
})()));

// iOS and iPadOS: every push must show a notification (userVisibleOnly), or
// WebKit revokes the subscription.
const MUST_SHOW = /iPhone|iPad|iPod/.test(self.navigator.userAgent) ||
  (/Macintosh/.test(self.navigator.userAgent) && self.navigator.maxTouchPoints > 1);
const HOUR_S = 3600;
const MUTE_ACTION_HOURS = 8;
const MUTE_ACTION_S = MUTE_ACTION_HOURS * HOUR_S;
const MS_PER_S = 1000;
const VISIBLE = "visible";
// A notification's buttons (`event.action`, "" for the notification itself).
const ACTION = Object.freeze({ REPLY: "reply", READ: "read", MUTE: "mute" });
// The notification tag is per chat (oc-push.js uses the same).
const TAG_PREFIX = "chat-";
// The buttons a push may ask for. "text" gives Reply a text field in the shade.
// The notification's images (push/web/icons): inline, so they need no route of their
// own and survive Open WebUI rebuilding /static.
// --- icons: generated by push/web/icons/make_icons.py, do not edit
const BADGE = "data:image/png;base64,";
const ICON = "data:image/png;base64,";
// --- end icons

const BUTTONS = {
  [ACTION.REPLY]: { action: ACTION.REPLY, title: "Reply", type: "text", placeholder: "Reply" },
  [ACTION.READ]: { action: ACTION.READ, title: "Mark as read" },
  [ACTION.MUTE]: { action: ACTION.MUTE, title: `Mute ${MUTE_ACTION_HOURS} h` },
};
// Where a reply that could not be sent waits for the page (oc-push.js reads it).
const DRAFTS = "oc-push-drafts";
const DEFAULT_TITLE = "Open WebUI", DEFAULT_BODY = "New reply";

// Several replies in one chat stack in its one notification, as in a messaging
// app: the title counts them, the body keeps the latest previews, newest last.
// The stack lives in the shown notification's data, so whatever closes it
// (opening the chat, Mark as read, a swipe) starts the next one from one.
const STACK_MAX_LINES = 5;
const STACK_LINE_CHARS = 120;
const ELLIPSIS = "…";
const SINGLE = 1;

function stackLine(text) {
  const line = String(text || "").replace(/\s+/g, " ").trim();
  return line.length > STACK_LINE_CHARS ? line.slice(0, STACK_LINE_CHARS - ELLIPSIS.length).trimEnd() + ELLIPSIS : line;
}

// `prev`: the chat's notification still shown (its data), or none. Returns what to show now.
function stacked(prev, p) {
  const name = p.title || DEFAULT_TITLE;
  const line = stackLine(p.body);
  const count = (prev?.count || 0) + 1;
  const lines = [...(prev?.lines || []), ...(line ? [line] : [])].slice(-STACK_MAX_LINES);
  return {
    title: count > SINGLE ? `${name} · ${count} new messages` : name,
    body: lines.length ? lines.join("\n") : DEFAULT_BODY,
    count, lines,
  };
}

self.addEventListener("push", (e) => {
  let p = {};
  try { p = e.data ? e.data.json() : {}; } catch (_) {}
  e.waitUntil((async () => {
    const wins = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
    // Open WebUI is in front of the user on this device, whatever chat is open:
    // nothing to tell, as in a messaging app (the page has its own cues).
    const inFront = wins.some((c) => c.focused && c.visibilityState === VISIBLE);
    const shown = MUST_SHOW || !inFront;
    if (shown) {
      const tag = TAG_PREFIX + (p.chat_id || "none");
      const [prev] = p.chat_id ? await self.registration.getNotifications({ tag }) : [];
      const s = stacked(prev?.data?.stack, p);
      await self.registration.showNotification(s.title, {
        body: s.body,
        tag,   // one per chat: a newer one replaces it (oc-push.js closes it when the chat is opened)
        renotify: true,   // each new reply sounds once
        icon: ICON,
        badge: BADGE,   // Android's small icon: only its alpha is drawn
        data: { url: p.url || "/", chat_id: p.chat_id || "", fn: p.fn || "", stack: { count: s.count, lines: s.lines } },
        // The function's NOTIFICATION_ACTIONS, in order; a push without them gets
        // no buttons. Android Chrome shows two (Notification.maxActions) and adds
        // its own "Unsubscribe" after them.
        actions: p.chat_id ? (p.actions || []).filter((a) => BUTTONS[a]).map((a) => BUTTONS[a]) : [],
      });
    }
    // Each decision, once acted on, to the open pages (`oc-push` messages), for tests and tools.
    for (const c of wins) c.postMessage({ type: "oc-push", shown, payload: p });
  })());
});

// Open WebUI's own API with the session cookie (same origin; Open WebUI reads
// its `token` cookie when there is no Authorization header).
async function api(path, body, signal) {
  const r = await fetch(path, {
    method: body ? "POST" : "GET", credentials: "same-origin", redirect: "error", signal,
    headers: body ? { "Content-Type": "application/json" } : {},
    body: body ? JSON.stringify(body) : undefined,
  });
  if (!r.ok) throw new Error(path + " " + r.status);
  return r.json();
}

// A message in the chat as the user, the way Open WebUI 0.13's chat page sends
// one: a single /api/chat/completions with the new user message under the
// chat's current leaf, which Open WebUI inserts with an empty reply and runs.
// A run still going is not stopped: the message reaches it like one sent from
// another tab (the OpenClaw Pipe steers it in, or queues it behind the run).
async function sendReply(chatId, text) {
  const chat = (await api("/api/v1/chats/" + chatId)).chat || {};
  const history = chat.history || {};
  const leaf = history.currentId ?? null;
  const model = (chat.models || [])[0] || history.messages?.[leaf]?.model;
  if (!model) throw new Error("no model");
  const uid = crypto.randomUUID(), aid = crypto.randomUUID();
  const userMessage = { id: uid, parentId: leaf, childrenIds: [], role: "user", content: text,
    timestamp: Math.floor(Date.now() / MS_PER_S), models: [model] };
  await api("/api/chat/completions", {
    stream: true, model, chat_id: chatId, id: aid, parent_id: leaf, user_message: userMessage,
    message_ids: [{ model_id: model, message_id: aid, modelIdx: 0 }],
    session_id: "oc-push-" + uid,
  });
  return uid;
}

// Mute a chat in the function's user valves: read, merge, write the whole set
// (Open WebUI's update replaces every user valve).
async function mute(fn, chatId, seconds, signal) {
  const path = "/api/v1/functions/id/" + fn + "/valves/user";
  const valves = (await api(path, undefined, signal)) || {};
  let mutes = {};
  try { mutes = JSON.parse(valves.mutes || "{}") || {}; } catch (_) {}
  mutes[chatId] = seconds ? Math.floor(Date.now() / MS_PER_S) + seconds : 0;
  await api(path + "/update", { ...valves, mutes: JSON.stringify(mutes) }, signal);
}

// Mark a chat read, as opening it does: Open WebUI 0.13 keeps the sidebar's
// unread dot on the server (chat.last_read_at), and sets it for one chat only
// through its Socket.IO event `events:chat` {type: "last_read_at"}; it then
// tells every open window of the user (`chat:list`), so the dot goes at once.
// The token comes from the session cookie (GET /api/v1/auths/), and is not kept.
// Engine.IO 4 packets (open, ping, pong) and Socket.IO's on the default namespace
// (connect, connect error, event): the first characters of each frame.
const EIO = Object.freeze({ OPEN: "0", PING: "2", PONG: "3" });
const SIO = Object.freeze({ CONNECT: "40", CONNECT_ERROR: "44", EVENT: "42" });
const SECURE_PROTOCOL = "https:";
// Open WebUI 0.13's read event, and its answer to the user's windows.
const READ_EVENT = "events:chat", READ_TYPE = "last_read_at";
const ANSWER_EVENT = "events", ANSWER_TYPE = "chat:list";
async function markRead(chatId, signal) {
  const { token } = await api("/api/v1/auths/", undefined, signal);
  if (!token) throw new Error("no session");
  const url = new URL("/ws/socket.io/?EIO=4&transport=websocket", self.location.origin);
  url.protocol = url.protocol === SECURE_PROTOCOL ? "wss:" : "ws:";
  const ws = new WebSocket(url);
  try {
    await new Promise((ok, fail) => {
      const timeout = () => done(fail, new Error("socket timeout"));
      const done = (f, v) => { signal.removeEventListener("abort", timeout); f(v); };
      if (signal.aborted) return timeout();
      signal.addEventListener("abort", timeout);
      ws.onerror = () => done(fail, new Error("socket error"));
      ws.onclose = () => done(fail, new Error("socket closed"));
      ws.onmessage = ({ data }) => { try { onFrame(String(data)); } catch (e) { done(fail, e); } };
      const onFrame = (data) => {
        if (data === EIO.PING) return ws.send(EIO.PONG);
        if (data.startsWith(SIO.CONNECT_ERROR)) return done(fail, new Error("socket refused"));
        if (data.startsWith(SIO.CONNECT)) {
          return ws.send(SIO.EVENT + JSON.stringify([READ_EVENT, { chat_id: chatId, data: { type: READ_TYPE } }]));
        }
        if (data.startsWith(SIO.EVENT)) {
          const [name, ev] = JSON.parse(data.slice(SIO.EVENT.length));
          if (name === ANSWER_EVENT && ev?.chat_id === chatId && ev.data?.type === ANSWER_TYPE) done(ok);
          return;
        }
        if (data.startsWith(EIO.OPEN)) ws.send(SIO.CONNECT + JSON.stringify({ token }));
      };
    });
  } finally {
    // Every path ends here (answered, refused, error, closed, out of time): no socket is left open.
    ws.onclose = ws.onerror = ws.onmessage = null;
    ws.close();
  }
}

// The page script answers "oc-open-chat" with an ack and opens the chat inside
// the app. An older page script never answers: after this long the window is
// navigated instead (a full load), and the console says why. A safety net for a
// page without the handler, not a guess at how long the page takes.
const OPEN_ACK_TIMEOUT_MS = 3000;
const OPEN_CHAT = "oc-open-chat", OPEN_CHAT_ACK = "oc-open-chat-ack";
const PAGE_ACT = "oc-push-act";   // a page asks for an action (see the message listener)
const CALLABLE = "function";
const opening = new Map();   // request id -> the ack's resolve

function askPage(win, url) {
  const id = crypto.randomUUID();
  return new Promise((ok) => {
    const timer = setTimeout(() => { opening.delete(id); ok(false); }, OPEN_ACK_TIMEOUT_MS);
    opening.set(id, () => { clearTimeout(timer); opening.delete(id); ok(true); });
    win.postMessage({ type: OPEN_CHAT, id, url });
  });
}

async function openChat(url) {
  const wins = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
  const win = wins.find((c) => new URL(c.url).origin === self.location.origin);
  if (!win) return self.clients.openWindow(url);   // nothing open: a full load is the only way
  // focus() is allowed only during a notification click (a user's tap).
  await win.focus().catch(() => {});
  // In the app, as a click in its sidebar would: no new document.
  if (await askPage(win, url)) return win;
  console.warn("oc-push: the page did not answer " + OPEN_CHAT + " within " + OPEN_ACK_TIMEOUT_MS + " ms; loading the chat");
  return win.navigate(url);
}

// Mute and Mark as read get this long, token fetch and socket included; past it
// the chat opens instead. Chrome lets a notification click open or focus a
// window for about 10 s, so the fallback must start well inside that.
// openChat focuses first (that needs the allowance); its wait for the page's
// answer and navigate() after it do not.
const ACTION_DEADLINE_MS = 6000;

// What a tap does. `action`: "" (the notification), "reply" or "mute".
async function act(action, data, reply) {
  const url = new URL(data.url || "/", self.location.origin).href;
  if (action === ACTION.MUTE && data.fn && data.chat_id) {
    try {
      await mute(data.fn, data.chat_id, MUTE_ACTION_S, AbortSignal.timeout(ACTION_DEADLINE_MS));
      return "muted";
    } catch (_) {
      await openChat(url);
      return "mute-failed";
    }
  }
  if (action === ACTION.READ && data.chat_id) {
    try {
      await markRead(data.chat_id, AbortSignal.timeout(ACTION_DEADLINE_MS));
      return "read";
    } catch (_) {
      // Not marked: opening the chat marks it read.
      await openChat(url);
      return "read-failed";
    }
  }
  if (action === ACTION.REPLY && data.chat_id) {
    const text = (reply || "").trim();
    if (text) {
      try {
        await sendReply(data.chat_id, text);
        return "sent";
      } catch (_) {
        // Not sent: the text waits for the chat page, which puts it in the
        // message box and says so. Never dropped.
        const drafts = await caches.open(DRAFTS);
        await drafts.put("/oc-push/draft/" + data.chat_id, new Response(JSON.stringify({ text, at: Date.now() })));
      }
    }
    await openChat(url + (url.includes("?") ? "&" : "?") + "oc-reply=" + (text ? "unsent" : "compose"));
    return text ? "reply-failed" : "compose";
  }
  await openChat(url);
  return "opened";
}

self.addEventListener("notificationclick", (e) => {
  e.notification.close();
  e.waitUntil(act(e.action, e.notification.data || {}, e.reply).then(async (result) => {
    for (const c of await self.clients.matchAll({ type: "window", includeUncontrolled: true })) {
      c.postMessage({ type: "oc-push-action", action: e.action, result });
    }
  }));
});

// A page of this origin can run the same actions (the e2e tests do; a page
// could call the same API itself, so this grants nothing new).
self.addEventListener("message", (e) => {
  const m = e.data || {};
  if (!e.source || new URL(e.source.url).origin !== self.location.origin) return;
  if (m.type === OPEN_CHAT_ACK) {
    // Only an id this worker handed out has a resolver.
    const answered = opening.get(m.id);
    if (typeof answered === CALLABLE) answered();
    return;
  }
  if (m.type === VERSION_CHECK) {
    // The page asks once it runs: told to reload if the kept app it got is not
    // this server's version (the answer can come before the page can hear it).
    const stale = staleApp.get(e.source.id);
    if (stale) e.waitUntil(stale.then((yes) => yes && e.source.postMessage({ type: NEW_VERSION })));
    return;
  }
  if (m.type !== PAGE_ACT) return;
  e.waitUntil(act(m.action, m.data || {}, m.reply).then((result) =>
    e.source.postMessage({ type: "oc-push-action", action: m.action, result })));
});

// The push service replaced the subscription: subscribe again with the same
// key. The page saves the new one on its next load (it has the user's token).
self.addEventListener("pushsubscriptionchange", (e) => {
  const options = e.oldSubscription?.options;
  if (options?.applicationServerKey) {
    e.waitUntil(self.registration.pushManager.subscribe(options));
  }
});


// --- Offline open (ELI-352) -------------------------------------------------
// The proxy replaces __OC_OFFLINE__ with its OFFLINE setting ("1" = on); served
// as a plain file it stays off.
const OFFLINE_SETTING = "__OC_OFFLINE__", ON = "1";
const OFFLINE = OFFLINE_SETTING === ON;
const SHELL = "oc-shell-v1";          // the app: its page, its hashed files, /static
const API_PREFIX = "oc-api-";         // + a hash of the user's token: one user's reads
const OURS = (name) => name === SHELL || name.startsWith(API_PREFIX);
// How long a request waits for a network that does not answer at all (lie-fi)
// before the kept copy is used. Not a speed setting: it never fires on a network
// that answers at Slow 3G speed. Measured 2026-11-05 on DevTools' Slow 3G (2 s
// round trip, 50 KB/s), a cold open of a chat: the slowest answer an open waits
// for the network for was the page itself, 2.09 s (the chat 2.08 s). A network
// silent for twice that is taken as gone.
const SLOW_3G_SLOWEST_MS = 2100;
const SILENT_FACTOR = 2;
const LIE_FI_MS = SLOW_3G_SLOWEST_MS * SILENT_FACTOR;
const SHELL_MAX = 400;                // entries kept, the oldest go first
const API_MAX = 300;
const PAGE_KEY = "/";                 // Open WebUI is one page for every route
// The /api/version answer the kept page came with: the kept app runs only
// against that same Open WebUI.
const VERSION_KEY = "/_oc/version";
const VERSION_PATH = "/api/version";
const IMMUTABLE = "/_app/immutable/";
// Kept files of this Open WebUI version: the kept copy at once, refreshed behind.
const SAVED_FIRST = ["/static/", "/assets/"];
const FRESH_FIRST = ["/_app/version.json", "/manifest.json"];
// The reads Open WebUI needs to draw the app. Its settings, models and config
// change rarely: the kept copy at once, refreshed behind (one open late at most).
const SHELL_READS = [
  /^\/api\/config$/, /^\/api\/models$/, /^\/api\/v1\/auths\/$/,
  /^\/api\/v1\/users\/user\/settings$/, /^\/api\/v1\/configs\/banners$/,
  /^\/api\/v1\/chats\/all\/tags$/, /^\/api\/v1\/chats\/[\w-]+\/tags$/,
  /^\/api\/v1\/functions\/$/, /^\/api\/v1\/skills\/$/, /^\/api\/v1\/tools\/$/,
];
// The chat list and an opened chat: what a notification is opened for, so the
// network's answer, the kept copy only offline. /api/version too: Open WebUI
// reloads itself when it changes while the page is open.
const FRESH_READS = [
  /^\/api\/version$/, /^\/api\/v1\/folders\/$/, /^\/api\/v1\/chats\/$/, /^\/api\/v1\/chats\/pinned$/,
  /^\/api\/v1\/chats\/[\w-]+$/,
];
// Profile pictures (a model's, a user's): <img> loads, with the session cookie and
// no Authorization header. Kept in the signed-in user's cache, the kept copy at
// once; a model with no picture answers with a redirect to Open WebUI's own icon.
const IMAGES = [/^\/api\/v1\/models\/model\/profile\/image$/, /^\/api\/v1\/users\/[\w-]+\/profile\/image$/];
const NEW_VERSION = "oc-new-version";   // to the page: reload, the app it runs is not this server's
const HTTP_OK = 200, HTTP_SERVER_ERROR = 500;
const HASH_HEX = 16, HEX = 16, BYTE_DIGITS = 2;
const SAME_ORIGIN = "basic", GET = "GET", NAVIGATE = "navigate", NO_STORE = "no-store", MANUAL = "manual";
const OPAQUE_REDIRECT = "opaqueredirect";
const never = new Promise(() => {});
const after = (ms) => new Promise((r) => setTimeout(r, ms));

// Only a clean answer is kept: never a redirect (an expired Cloudflare Access
// session answers with one), an error or another site's answer.
const keepable = (res) => res && res.status === HTTP_OK && res.type === SAME_ORIGIN && !res.redirected;
// A picture may come through a redirect on this site (to Open WebUI's default icon).
const keepableImage = (res) => res && res.status === HTTP_OK && res.type === SAME_ORIGIN;
// The network gave nothing usable: no answer, or the server (or the tunnel in
// front of it) is down.
const down = (res) => !res || res.status >= HTTP_SERVER_ERROR;

async function dropCaches(which) {
  for (const name of await caches.keys()) if (OURS(name) && which(name)) await caches.delete(name);
}

async function trim(cache, max) {
  const keys = await cache.keys();
  for (const k of keys.slice(0, Math.max(0, keys.length - max))) await cache.delete(k);
}

// The network within `ms`, else the cached copy; the network answer, when it
// comes, still refreshes the cache (`isIt` can refuse an answer that is not the
// thing being kept).
async function freshFirst(e, req, cacheName, key, ms, onFresh, isIt) {
  const cache = await caches.open(cacheName);
  const net = shared(req).then(async (res) => {
    if (keepable(res) && (!isIt || await isIt(res.clone()))) {
      await cache.put(key, res.clone());
      if (onFresh) await onFresh(res.clone(), cache);
    }
    return res;
  }, () => null);
  e.waitUntil(net);
  const first = await Promise.race([net, after(ms)]);
  if (first !== undefined && !down(first)) return first;
  const saved = await cache.match(key);
  if (saved) return saved;
  const res = await net;
  return res || Response.error();
}

// A read that fails on the network (no answer: a TypeError, not an HTTP error) is
// asked once more at once. A change of network (Wi-Fi to mobile) fails every
// request on its way with ERR_NETWORK_CHANGED, and Open WebUI does not ask again:
// a read it needs to start fails and the app stays half drawn. The second
// attempt goes out on the new network. Only reads (GET) come here.
const again = (input, init) => fetch(input, init).catch(() => fetch(input, init));

// The same read asked again while the first is on its way (Open WebUI loads an
// opened chat twice) shares that one request: one round trip, not two.
const inFlight = new Map();
function shared(req) {
  const key = req.url + "\n" + (req.headers.get("authorization") || "");
  let p = inFlight.get(key);
  if (!p) {
    p = again(req);
    inFlight.set(key, p);
    const done = () => inFlight.delete(key);
    p.then(done, done);
  }
  return p.then((res) => res.clone());
}

// The kept copy at once when there is one; the network's answer refreshes it for
// the next open.
async function savedFirst(e, req, cacheName, key, onFresh, keep = keepable) {
  const cache = await caches.open(cacheName);
  const net = again(req).then(async (res) => {
    if (keep(res)) {
      await cache.put(key, res.clone());
      if (onFresh) await onFresh(res.clone(), cache);
    }
    return res;
  }, () => null);
  e.waitUntil(net);
  return (await cache.match(key)) || (await net) || Response.error();
}

const bootVersion = new Map();   // page (client id) -> its load's /api/version answer (a promise)
const staleApp = new Map();      // page (client id) -> whether the kept app it got is another version
const VERSION_CHECK = "oc-version-check";   // from the page: was my app the server's version?
const JSON_TYPE = { "content-type": "application/json" };

// A page load. The kept app opens at once when it was kept with its version, and
// this Open WebUI's /api/version is asked alongside it. Another version (a newer
// Open WebUI): every cache goes and the page is told to reload, once (oc-push.js),
// onto the server's own app. A redirect instead of a version (an expired
// Cloudflare Access session): the kept page goes, and the reload gets the login.
// Kept without a version (an older worker kept it): the kept app is used only
// once the version matches, as before; with no network, at once; with a network
// that says nothing for LIE_FI_MS, too, and told to reload as above.
async function navigate(e, req) {
  const net = again(req).catch(() => null);
  let redirected = false;
  const asked = again(VERSION_PATH, { cache: NO_STORE, redirect: MANUAL })
    .then((r) => {
      redirected = r.type === OPAQUE_REDIRECT;
      return r.ok ? r.text() : null;
    }, () => null);
  const cache = await caches.open(SHELL);
  const saved = await cache.match(PAGE_KEY);
  const kept = await (await cache.match(VERSION_KEY))?.text();
  const other = (v) => v !== null && v !== kept;
  const version = asked.then(async (v) => {
    if (other(v)) await dropCaches(() => true);
    // A login instead of a version: the kept page is not opened again.
    else if (redirected) await cache.delete(PAGE_KEY);
    return v;
  });
  // The page's own first /api/version read gets this load's answer: no second round trip.
  bootVersion.clear();
  bootVersion.set(e.resultingClientId, asked);
  // A copy taken as the answer comes, before the page reads its body.
  e.waitUntil(keepPage(net.then((res) => res && res.clone()), version));
  if (!saved) return (await net) || Response.error();
  if (kept !== undefined) {
    // The kept app is that version, so its own /api/version read gets that at once:
    // Open WebUI waits for it while it starts, and the server's answer is only for
    // the check here (a silent network leaves the app running, the check pending).
    bootVersion.set(e.resultingClientId, Promise.resolve(kept));
    const stale = version.then((v) => other(v) || redirected);
    staleApp.clear();
    staleApp.set(e.resultingClientId, stale);
    e.waitUntil(stale.then(async (yes) => {
      if (yes) (await self.clients.get(e.resultingClientId))?.postMessage({ type: NEW_VERSION });
    }));
    return saved;
  }
  const first = await Promise.race([
    net.then((res) => (down(res) ? never : { res })),
    version.then((v) => (v === null ? never : { v })),
    Promise.all([net, version]).then(([res, v]) => (down(res) && v === null ? {} : never)),
    after(LIE_FI_MS).then(() => ({ silent: true })),
  ]);
  if (first.res) return first.res;
  if (first.v !== undefined && first.v !== kept) return (await net) || Response.error();
  if (first.silent) {
    // Nothing heard: the page's /api/version goes the usual way (the kept copy, as any read).
    bootVersion.delete(e.resultingClientId);
    e.waitUntil(version.then(async (v) => {
      if (other(v)) (await self.clients.get(e.resultingClientId))?.postMessage({ type: NEW_VERSION });
    }));
  }
  return saved;
}

// A page answer that is Open WebUI's app is kept, with the version it came with.
async function keepPage(net, version) {
  const [res, v] = await Promise.all([net, version]);
  if (!keepable(res) || !(await isAppPage(res.clone()))) return;
  const cache = await caches.open(SHELL);
  await cache.put(PAGE_KEY, res.clone());
  if (v === null) await cache.delete(VERSION_KEY);
  else await cache.put(VERSION_KEY, new Response(v));
  await pruneShell(res.clone(), cache);
}

// A new page means a new Open WebUI build: its hashed files are new too, so the
// old ones go.
async function pruneShell(page, cache) {
  const html = await page.text();
  const used = new Set(html.match(/\/_app\/immutable\/[^"'\s)]+/g) || []);
  if (!used.size) return;
  const keys = await cache.keys();
  const stamp = await cache.match("/_oc/page-files");
  const before = stamp ? await stamp.text() : "";
  const now = [...used].sort().join("\n");
  if (before && before !== now) {
    for (const k of keys) {
      const path = new URL(k.url).pathname;
      if (path.startsWith(IMMUTABLE) && !used.has(path)) await cache.delete(k);
    }
  }
  await cache.put("/_oc/page-files", new Response(now));
  await trim(cache, SHELL_MAX);
}

// Open WebUI's page loads its hashed files; a login page (Cloudflare Access) or
// an error page does not, and is never kept as the app.
const isAppPage = async (res) => (await res.text()).includes(IMMUTABLE);

async function cacheFirst(e, req) {
  const cache = await caches.open(SHELL);
  const saved = await cache.match(req);
  if (saved) return saved;
  const res = await again(req);
  if (keepable(res)) e.waitUntil(cache.put(req, res.clone()));
  return res;
}

// One user's reads in one cache, named by a hash of their token: a sign-out or
// another user on this device starts a new one, and the others are deleted.
let apiCache = "";
async function apiCacheFor(auth) {
  const session = signOuts;
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(auth));
  const name = API_PREFIX + [...new Uint8Array(digest)].map((b) => b.toString(HEX).padStart(BYTE_DIGITS, "0")).join("").slice(0, HASH_HEX);
  // Signed out meanwhile: no user's cache is current.
  if (session === signOuts && name !== apiCache) {
    apiCache = name;
    await dropCaches((n) => n.startsWith(API_PREFIX) && n !== name);
  }
  return name;
}

// --- Kept chats: a chat opened before shows at once ------------------------
// Open WebUI reads the whole chat (every message, as JSON: megabytes for a long
// chat) on every open, and draws nothing of it before the last byte. A chat this
// user opened before is answered from the copy kept of it, at once, marked
// (KEPT_HEADER), and the network's copy is fetched behind it. Open WebUI reads an
// opened chat twice: to draw it (loadChat) and again once it has joined the chat's
// room on the socket (refreshChat, also after a reconnect), merging what that read
// gets into the chat on screen. A page that was given the kept copy waits for the
// network's on its next read of that chat, so that second read swaps the fresh
// copy in: Open WebUI's own refresh, no timer. If the network's copy came before
// that read, the read gets it from the cache, not a second download. The page
// script (oc-push.js) shows "Updating…" and locks the message box while a chat on
// screen is the kept copy: a message sent on it could branch off an old point.
// The proxy replaces __OC_CHAT_CACHE__ with its CHAT_CACHE setting ("1" = on);
// it works with offline open on (the kept chats are in the user's offline cache).
const CHAT_CACHE_SETTING = "__OC_CHAT_CACHE__";
const CHATS_KEPT = OFFLINE && CHAT_CACHE_SETTING === ON;
const CHAT_READ = /^\/api\/v1\/chats\/[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/;
const KEPT_HEADER = "x-oc-kept";      // on a chat answered from the kept copy (oc-push.js)
const ANSWERED_HEADER = "x-oc-answered";   // on a kept copy whose last message is a finished reply
// From the page script (oc-push.js): OPEN_READ on Open WebUI's first read of a chat
// after the page went to it; OWN_READ on the script's own reads (a chat's folder).
const OPEN_READ = "x-oc-open";
const OWN_READ = "x-oc-own", OWN_FRESH = "fresh";
const MIB = 1048576;
// A chat bigger than this is not kept (the network on every open): keeping it
// takes the whole chat through the worker's memory on every open. The biggest real
// chats (2026-11-06) are 31, 20 and 16 MB: each one is kept.
const CHAT_MAX_MIB = 32;
const CHAT_MAX_BYTES = CHAT_MAX_MIB * MIB;
// All the kept chats of a user; the least recently opened go first. Room for the
// three biggest real chats (67 MB) and as much again of ordinary ones (tens of KB
// to a few MB each), far under the storage Chrome gives a site on a phone.
const CHATS_MAX_MIB = 128;
const CHATS_MAX_BYTES = CHATS_MAX_MIB * MIB;
const CHATS_INDEX = "/_oc/chats";     // in the user's cache: {url: [bytes, last opened]}
const SIGNOUT_PATH = "/api/v1/auths/signout";
// Headers of the network's answer that do not hold for the kept body (decoded, its own length).
const NOT_KEPT_HEADERS = ["content-encoding", "content-length"];

const chatFetches = new Map();   // cache + url -> {res: the network's answer (a promise), joined}
// cache + url: the kept copy is the network's, fetched behind an open no read has waited for.
const chatFresh = new Set();
// To the pages: a chat's network copy is kept (oc-push.js: a page whose Open WebUI
// will not refresh the chat, its socket down, reloads into it).
const CHAT_FRESH = "oc-chat-fresh";
// Sign-outs so far: a read that began before one keeps nothing (its user is gone).
let signOuts = 0;

// The index is read and written one change at a time.
let indexing = Promise.resolve();
function withIndex(cache, change) {
  indexing = indexing.then(async () => {
    const index = (await (await cache.match(CHATS_INDEX))?.json().catch(() => null)) || {};
    await change(index);
    await cache.put(CHATS_INDEX, new Response(JSON.stringify(index), { headers: JSON_TYPE }));
  }).catch(() => {});
  return indexing;
}

async function keepChat(cache, url, res) {
  const body = await res.blob();
  if (body.size > CHAT_MAX_BYTES) return forgetChat(cache, url);
  const headers = new Headers(res.headers);
  for (const h of NOT_KEPT_HEADERS) headers.delete(h);
  headers.set(KEPT_HEADER, ON);
  if (answered(JSON.parse(await body.text()))) headers.set(ANSWERED_HEADER, ON);
  await cache.put(url, new Response(body, { status: res.status, statusText: res.statusText, headers }));
  return withIndex(cache, async (index) => {
    index[url] = [body.size, Date.now()];
    // Chats an older worker kept (offline open) are outside the index: they go, and
    // each is kept again, counted, on its next open.
    for (const k of await cache.keys()) {
      if (CHAT_READ.test(new URL(k.url).pathname) && !index[k.url]) await cache.delete(k);
    }
    const oldestFirst = Object.entries(index).sort((a, b) => a[1][1] - b[1][1]);
    let total = oldestFirst.reduce((n, [, [bytes]]) => n + bytes, 0);
    for (const [old, [bytes]] of oldestFirst) {
      if (total <= CHATS_MAX_BYTES) break;
      await cache.delete(old);
      delete index[old];
      total -= bytes;
    }
  });
}

async function forgetChat(cache, url) {
  await cache.delete(url);
  return withIndex(cache, (index) => { delete index[url]; });
}

// The chat's last message is a finished reply: the one Open WebUI 0.13's loadChat
// goes to (current_message_id, or the history's currentId).
const ASSISTANT = "assistant";
function answered(chat) {
  const history = chat?.chat?.history;
  const id = history?.messages?.[chat.current_message_id] ? chat.current_message_id : history?.currentId;
  const last = history?.messages?.[id];
  return last?.role === ASSISTANT && last.done === true;
}

// Open WebUI draws an opened chat only once it also has the chat's running tasks
// (loadChat's getTaskIdsByChatId, after the chat and its tags). The answer counts only
// when the last message is not a finished reply (loadChat keeps the tasks then); for
// a chat opened from a kept copy that ends with one, it changes nothing, and waiting
// for it on a slow network is what kept the chat from drawing: "none", at once. Every
// read of them until the network has answered for the chat: Open WebUI also reads
// them when its socket connects, before or after loadChat's (only the first getting
// "none" left loadChat waiting). After that, the network's (a reconnect's).
const TASKS_READ = /^\/api\/tasks\/chat\/([0-9a-f-]+)$/;
const NO_TASKS = '{"task_ids":[]}';
const tasksMoot = new Set();   // cache name + chat id: opened from a kept copy that ends answered

// The kept copy, told apart from the network's by nothing: it is the network's.
function asFresh(res) {
  const headers = new Headers(res.headers);
  headers.delete(KEPT_HEADER);
  return new Response(res.body, { status: res.status, statusText: res.statusText, headers });
}

async function toPages(message) {
  for (const c of await self.clients.matchAll({ type: "window" })) c.postMessage(message);
}

// The network's copy of a chat, one request however many reads wait for it. A cache
// that cannot take it (storage full) changes nothing for the reads: they get the
// network's answer, and the kept copy is not taken for it.
function fetchChat(e, req, cache, key, session) {
  let f = chatFetches.get(key);
  if (!f) {
    // forOpen: it is the copy behind an open's kept answer; joined: a read waited for it.
    f = { joined: false, forOpen: false };
    const mine = f;
    f.res = shared(req).then(async (res) => {
      if (session !== signOuts) return res;
      // The network answered for the chat: from now on its tasks are the network's too.
      if (!down(res)) tasksMoot.delete(key.split("\n")[0] + "\n" + new URL(req.url).pathname.split("/").pop());
      try {
        if (keepable(res)) {
          await keepChat(cache, req.url, res.clone());
          // Only behind an open: an own read's fetch is not what the page's next read
          // may take without asking (a reply since would be missed).
          if (mine.forOpen && !mine.joined) chatFresh.add(key);
          await toPages({ type: CHAT_FRESH, path: new URL(req.url).pathname });
        // Deleted, or no longer this user's: not opened from the kept copy again.
        } else if (!down(res) && !res.redirected) await forgetChat(cache, req.url);
      } catch (_) {}
      return res;
    }, () => null).finally(() => chatFetches.delete(key));
    chatFetches.set(key, f);
  }
  e.waitUntil(f.res);
  return f;
}

// Open WebUI's read of a chat comes as one of three (oc-push.js tells them apart):
// - an open (OPEN_READ: its first read after the page went to the chat): the kept
//   copy at once, the network's fetched behind it;
// - any other read (its refresh once it joined the chat's room, a reload of the
//   chat): the network's copy, the one being fetched if it is on its way, or the one
//   fetched behind the open if it came first (no second download);
// - the page script's own (OWN_READ): the kept copy if there is one, or the network's
//   with OWN_FRESH (the chat's folder before a mute); it changes nothing.
async function chatRead(e, req, name, session) {
  if (session !== signOuts) return again(req);
  const cache = await caches.open(name);
  const key = name + "\n" + req.url;
  const saved = (await cache.match(req.url)) ?? null;
  // A copy an older worker kept (offline open) has no mark: not opened from.
  const kept = saved?.headers.has(KEPT_HEADER) ? saved : null;
  const own = req.headers.get(OWN_READ);
  // The network's copy. When it does not come (no network, the server down), the
  // copy kept: Open WebUI empties the chat and goes home on a failed read. A copy
  // an older worker kept is used, as offline open did, when the network says
  // nothing for LIE_FI_MS; a kept chat is on screen already (marked) while it waits.
  const waited = async (f) => {
    if (!own) f.joined = true;
    const late = saved && !kept ? after(LIE_FI_MS).then(() => saved) : never;
    const res = await Promise.race([f.res.then((r) => r?.clone()), late]);
    return down(res) ? saved || res || Response.error() : res;
  };
  if (own) return own !== OWN_FRESH && saved ? saved : waited(fetchChat(e, req, cache, key, session));
  if (req.headers.has(OPEN_READ)) {
    chatFresh.delete(key);
    // Not kept: the network's (the copy on its way, if the page script's own read asked first).
    if (!kept) return waited(fetchChat(e, req, cache, key, session));
    fetchChat(e, req, cache, key, session).forOpen = true;
    if (kept.headers.has(ANSWERED_HEADER)) tasksMoot.add(name + "\n" + new URL(req.url).pathname.split("/").pop());
    e.waitUntil(withIndex(cache, (index) => { if (index[req.url]) index[req.url][1] = Date.now(); }));
    return kept;
  }
  if (!chatFetches.has(key) && kept && chatFresh.delete(key)) return asFresh(kept);
  return waited(fetchChat(e, req, cache, key, session));
}

// A sign-out: nothing of that user's stays on the device, and a read on its way
// (its user's cache name being worked out) keeps nothing either.
async function signedOut() {
  signOuts++;
  apiCache = "";
  chatFetches.clear();
  chatFresh.clear();
  tasksMoot.clear();
  await dropCaches((n) => n.startsWith(API_PREFIX));
}

self.addEventListener("fetch", (e) => {
  const req = e.request;
  if (!OFFLINE) {
    // Turned off: a cache the previous worker still wrote after this one's
    // activate (its requests on their way) goes on the next page load.
    if (req.mode === NAVIGATE) e.waitUntil(dropCaches(() => true));
    return;
  }
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  const path = url.pathname;
  if (path === SIGNOUT_PATH) e.waitUntil(signedOut());
  if (req.method !== GET) return;
  if (req.mode === NAVIGATE) {
    e.respondWith(navigate(e, req));
  } else if (path.startsWith(IMMUTABLE)) {
    e.respondWith(cacheFirst(e, req));
  } else if (SAVED_FIRST.some((p) => path.startsWith(p))) {
    e.respondWith(savedFirst(e, req, SHELL, req));
  } else if (FRESH_FIRST.some((p) => path.startsWith(p))) {
    e.respondWith(freshFirst(e, req, SHELL, req, LIE_FI_MS));
  } else if (IMAGES.some((r) => r.test(path))) {
    // Whose: the user whose reads came last (a sign-in or another user changes that
    // cache, and the old one goes with its pictures). None yet: the network only.
    if (apiCache) {
      e.respondWith(savedFirst(e, req, apiCache, req.url, async (_res, cache) => trim(cache, API_MAX), keepableImage));
    }
  } else if (path === VERSION_PATH && bootVersion.has(e.clientId)) {
    const asked = bootVersion.get(e.clientId);
    bootVersion.delete(e.clientId);
    e.respondWith(asked.then((v) => (v === null ? freshFirst(e, req, SHELL, req.url, LIE_FI_MS)
      : new Response(v, { headers: JSON_TYPE }))));
  } else if (CHATS_KEPT && TASKS_READ.test(path) && req.headers.get("authorization")) {
    const id = path.match(TASKS_READ)[1];
    e.respondWith(apiCacheFor(req.headers.get("authorization")).then((name) => (tasksMoot.has(name + "\n" + id)
      ? new Response(NO_TASKS, { headers: JSON_TYPE }) : again(req))));
  } else {
    const fresh = FRESH_READS.some((r) => r.test(path));
    if (!fresh && !SHELL_READS.some((r) => r.test(path))) return;
    const auth = req.headers.get("authorization");
    if (CHATS_KEPT && auth && CHAT_READ.test(path) && !url.search) {
      const session = signOuts;
      e.respondWith(apiCacheFor(auth).then((name) => chatRead(e, req, name, session)));
      return;
    }
    const read = (name, onFresh) => (fresh
      ? freshFirst(e, req, name, req.url, LIE_FI_MS, onFresh)
      : savedFirst(e, req, name, req.url, onFresh));
    // Public reads (/api/config, /api/version) go with the app; a user's in their own
    // cache, unless they signed out meanwhile.
    const session = signOuts;
    e.respondWith(auth ? apiCacheFor(auth).then((name) => (session === signOuts
      ? read(name, async (_res, cache) => trim(cache, API_MAX)) : again(req)))
      : read(SHELL));
  }
});
